// Saniteer tekstinvoer: verwijder single quotes voor SQLite-escaping
function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/'/g, "''").trim();
}

// Valideer getal
function safeFloat(val, fallback) {
  const n = parseFloat(val);
  return isNaN(n) ? fallback : Math.abs(n);
}

// Valideer BTW percentage (mag alleen 0, 9 of 21 zijn)
function safeBtw(val) {
  const allowed = [0, 9, 21];
  const n = parseInt(val);
  return allowed.includes(n) ? n : 21;
}

// Valideer datum (JJJJ-MM-DD formaat)
function safeDate(val) {
  const d = String(val || '');
  return /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : new Date().toISOString().split('T')[0];
}

// Valideer grootboekcode (mag alleen 4 cijfers zijn)
function safeCode(val) {
  const raw = String(val || '').split(' ')[0];
  return /^\d{4}$/.test(raw) ? raw : '4400';
}

const body = $input.first().json.body || {};

const leverancier = sanitize(body.leverancier);
const omschrijving = sanitize(body.omschrijving);
const bedrag = safeFloat(body.bedrag, 0);
const btwPct = safeBtw(body.btw);
const datum = safeDate(body.datum);
const grootboekCode = safeCode(body.grootboek);

const btwBedrag = Math.round(bedrag * btwPct / 100 * 100) / 100;
const totaal = Math.round((bedrag + btwBedrag) * 100) / 100;

return [{
  json: {
    leverancier,
    omschrijving,
    bedrag,
    btw_percentage: btwPct,
    btw_bedrag: btwBedrag,
    totaal,
    grootboek_code: grootboekCode,
    datum
  }
}];

